est = 1008;const short cCalculator = 1009;const short cScrollingTest = 1011;const short cFormatDialog = 1012;const short cModelessBeepDialog = 1013;const short cMessageWindoid = 1014;const short cBalloons = 1015;const short cAdornment = 1016;const short cViewInspector = 1017;const short cTargetInspector = 1018;const short cShowError = 1019;const short cLastItem = 1019;const short cPopupExample = 1100;const short cTextStyleChanged = 1102;const short cResetTextStyle = 1103;//----------------------------------------------------------------------------------------struct FondRecord{	FamRec familyStuff;	short noOfFonts;	struct	{		short size;		short style;		short resID;	} fontStuff[1001];};typedef FondRecord* FondPointer, ** FondHandle;long gMonthlyValues[13];IDType gMonthIDs[13];//========================================================================================// Global Functions//========================================================================================static bool GetFontNumber(CStr255_AC& fontName, short& fontNumber);//========================================================================================// CLASS TTestApplication//========================================================================================#undef Inherited#define Inherited TApplication//----------------------------------------------------------------------------------------// TTestApplication constructor//----------------------------------------------------------------------------------------TTestApplication::TTestApplication()	:	TApplication(kFileType, kSignature){#if !qMSWindows	const char* monthIDs = "jan feb mar apr may jun jul aug sep oct nov dec ";#endif	fLaunchWithNewDocument = false;				// Suppress the creation of a new document at launch	for (short i = 0; i < 12; ++i)	{		gMonthlyValues[i] = (i + 1) * 100;	}#if qMSWindows	// because of endian issues, this must be done manually in Windows!	gMonth